function varargout = load(varargin)
% LOAD  Spinach-scoped wrapper of Octave's load.
%
% MATLAB stores a table in a MAT file as a MATLAB object (MCOS subsystem), which
% Octave cannot decode: it returns an opaque struct with an 'MCOS' field. Spinach
% keeps its isotope database so (etc/isotopes.mat, variable 'isotopes'); the MAT
% file is generated by Spinach's etc/build_isotopes.m from the shipped
% etc/isotopes.tsv. For that variable this wrapper builds the same table from the
% TSV, following build_isotopes step for step, as a table stand-in (text columns
% as string-array stand-ins). Every other load is Octave's, unchanged.

    if nargout == 0
        builtin('load', varargin{:});   % load into the caller is not used by Spinach
        error('load: Spinach-scoped wrapper only supports S = load(...)');
    end
    S = builtin('load', varargin{:});
    file = varargin{1};
    if isstruct(S)
        f = fieldnames(S);
        for k = 1:numel(f)
            v = S.(f{k});
            if isstruct(v) && isfield(v, 'MCOS')
                [d, stem] = fileparts(file);
                tsv = fullfile(d, [stem '.tsv']);
                if strcmp(f{k}, 'isotopes') && exist(tsv, 'file')
                    S.(f{k}) = isotopes_from_tsv(tsv);
                else
                    error('load: %s holds a MATLAB object (%s) that Octave cannot read', file, f{k});
                end
            end
        end
    end
    varargout{1} = S;
end

function T = isotopes_from_tsv(source_file)
% Spinach's build_isotopes.m, with readtable replaced by a typed textscan.
    names = {'isotope','kind','state','coverage_status','z','a','element', ...
             'element_name','spin','spin_status','mag_moment','gn','gamma', ...
             'abundance','abund_low','abund_high','abund_basis','quad_moment', ...
             'radioactive','half_life','half_life_kind','source_dois','notes'};
    types = {'string','string','string','string','double','double','string', ...
             'string','double','string','double','double','double','double', ...
             'double','double','string','double','logical','double','string', ...
             'string','string'};
    fmt = strjoin(cellfun(@(t) ifelse(strcmp(t, 'string'), '%s', '%f'), types, 'UniformOutput', false), '');
    fid = fopen(source_file, 'r');
    C = textscan(fid, fmt, 'Delimiter', '\t', 'HeaderLines', 1, 'Whitespace', '', ...
                 'EndOfLine', '\n', 'ReturnOnError', false);
    fclose(fid);
    cols = cell(1, numel(names));
    for k = 1:numel(names)
        switch types{k}
            case 'string',  cols{k} = mrsuite_strings(C{k});
            case 'logical', cols{k} = logical(C{k});
            otherwise,      cols{k} = C{k};
        end
    end
    T = table(cols{:}, 'VariableNames', names);

    mu_n = 5.0507837393e-27; hbar = 6.62607015e-34 / (2 * pi);
    is_nucleus = T.kind == "nuclide";
    spin = T.spin; mag = T.mag_moment; gn = T.gn; gamma = T.gamma; quad = T.quad_moment;
    nonzero = is_nucleus & spin > 0;
    gn(nonzero) = mag(nonzero) ./ spin(nonzero);
    derived = nonzero & ~isnan(mag) & isnan(gamma);
    gamma(derived) = gn(derived) * mu_n / hbar;
    zero_spin = is_nucleus & spin == 0;
    mag(zero_spin) = 0; gamma(zero_spin) = 0;
    quad(is_nucleus & spin < 1) = 0;
    T.gn = gn; T.gamma = gamma; T.mag_moment = mag; T.quad_moment = quad;
    dois = cellstr(T.source_dois);
    dois(derived) = strcat(dois(derived), '; gamma,constants: 10.1103/RevModPhys.97.025002');
    T.source_dois = mrsuite_strings(dois);

    T.Properties.RowNames = cellstr(T.isotope);
    units = repmat({''}, 1, numel(names));
    units{11} = 'nuclear magneton'; units{13} = 'rad/(s*T)';
    units{14} = 'fraction'; units{15} = 'fraction'; units{16} = 'fraction';
    units{18} = 'barn'; units{20} = 's';
    T.Properties.VariableUnits = units;
    T.Properties.Description = 'Literature-sourced nuclear and particle spin properties';
    T.Properties.UserData = struct('schema', 1, 'constants', 'CODATA2022', ...
        'half_life_note', 'Inf denotes classified stable; qualifiers and source conditions remain explicit');
end

function r = ifelse(c, a, b)
    if c, r = a; else, r = b; end
end
